def compute(vars):
    v1 = vars["v1"]  # New debt issuances in billions
    v2 = vars["v2"]  # Net debt reductions in millions
    if v2 == 0:
        return None

    v1_millions = v1 * 1000
    value = v1_millions / v2

    return {
        "value": value,
        "trace": {
            "v1_millions": v1_millions,
            "denominator": v2,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
